private static long adjustMemoryPercentage(long percentage) throws SQLServerException {
        checkForNegativeValue(percentage);
        if (percentage > 90)
            return (long) (0.9 * getMaxMemory());
        else
            return (long) ((percentage) / 100.0 * getMaxMemory());
    }

